import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as n,o as i,c as e,a2 as p}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Концепции","description":"","frontmatter":{},"headers":[],"relativePath":"ru/concepts/overview.md","filePath":"ru/concepts/overview.md","lastUpdated":1784903584000}'),t={name:"ru/concepts/overview.md"};function o(l,s,c,r,h,d){return i(),e("div",null,[...s[0]||(s[0]=[p('<h1 id="концепции" tabindex="-1">Концепции <a class="header-anchor" href="#концепции" aria-label="Permalink to &quot;Концепции&quot;">​</a></h1><h2 id="архитектура" tabindex="-1">Архитектура <a class="header-anchor" href="#архитектура" aria-label="Permalink to &quot;Архитектура&quot;">​</a></h2><p>swag2mcp выступает в роли моста между спецификациями API и LLM-агентами:</p><img src="'+a+`" width="800" alt="Архитектура swag2mcp"><h2 id="основные-понятия" tabindex="-1">Основные понятия <a class="header-anchor" href="#основные-понятия" aria-label="Permalink to &quot;Основные понятия&quot;">​</a></h2><p><strong>Спецификация</strong> — логический контейнер, представляющий домен или сервис API (например, YouTube, Binance, Open-Meteo). Каждая спецификация имеет уникальный <code>domain</code>, <code>base_url</code>, опциональную <code>auth</code> и содержит одну или несколько коллекций. Вы также можете задать <code>llm_instruction</code> — короткую подсказку, которая внедряется в системный промпт swag2mcp и сообщает LLM, для чего предназначена эта спецификация и когда её использовать. Подробнее: <a href="./specs">Спецификации</a>.</p><p><strong>Коллекция</strong> — один файл OpenAPI/Swagger/Postman, описывающий конкретный API. Она указывает на <code>location</code> (URL или локальный путь к файлу). Одна спецификация может иметь несколько коллекций — например, спецификация &quot;meteo&quot; может содержать коллекции &quot;Прогноз&quot;, &quot;Качество воздуха&quot; и &quot;Морские данные&quot;, каждая из которых указывает на свой файл спецификации. Подробнее: <a href="./collections">Коллекции</a>.</p><p><strong>Тег</strong> — категория эндпоинтов внутри коллекции. Помогает LLM точнее находить нужные операции. Подробнее: <a href="./tags">Теги</a>.</p><p><strong>Эндпоинт</strong> — конкретный HTTP-метод + путь (например, <code>GET /api/users</code>). LLM может найти эндпоинт по описанию, изучить его параметры и схемы, а затем вызвать его. Подробнее: <a href="./endpoints">Эндпоинты</a>.</p><p><strong>Рабочая область</strong> — директория, в которой swag2mcp хранит конфиг, кэш спецификаций, сохранённые ответы и скрипты аутентификации. Подробнее: <a href="./workspace">Рабочая область</a>.</p><h2 id="как-это-работает" tabindex="-1">Как это работает <a class="header-anchor" href="#как-это-работает" aria-label="Permalink to &quot;Как это работает&quot;">​</a></h2><ol><li><p><strong>Добавьте спецификацию или коллекцию</strong> — определите её в YAML-конфиге (<code>~/.swag2mcp/swag2mcp.yaml</code>). Например:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp парсит каждую коллекцию</strong> — создаёт теги и эндпоинты, индексирует их для поиска.</p></li><li><p><strong>LLM находит нужный эндпоинт</strong> — через MCP-инструменты (<code>search</code>, <code>endpoint_by_tag</code>, <code>inspect</code>) LLM ищет подходящий эндпоинт по описанию, изучает его параметры и схему запроса.</p></li><li><p><strong>LLM вызывает эндпоинт</strong> — через MCP-инструмент <code>invoke</code> LLM отправляет запрос. swag2mcp проверяет каждый входной параметр на соответствие OpenAPI-схеме эндпоинта (параметры пути, запроса, заголовки, тело запроса) перед выполнением вызова. Если что-то не соответствует схеме, LLM получает понятную ошибку с объяснением проблемы. После проверки swag2mcp выполняет реальный HTTP-вызов и возвращает результат.</p></li><li><p><strong>Результат возвращается LLM</strong> — ответ API передаётся обратно агенту. Большие ответы сохраняются в рабочую область и могут быть исследованы с помощью трёх специальных MCP-инструментов: <code>response_outline</code> (просмотр структуры), <code>response_compress</code> (сжатие до репрезентативного образца) и <code>response_slice</code> (извлечение конкретных фрагментов).</p></li></ol><p>swag2mcp — это мост между LLM и миром API. Вы добавляете спецификации API, а LLM — через протокол MCP — находит нужные эндпоинты, изучает их документацию и вызывает их. Всё, что вам нужно сделать — добавить спецификацию и запустить MCP-сервер.</p><blockquote><p><strong>Конфиг можно редактировать в любое время.</strong> YAML-файл конфигурации (<code>~/.swag2mcp/swag2mcp.yaml</code>) можно редактировать вручную — добавлять спецификации, менять аутентификацию, настраивать параметры. После каждого изменения перезапустите MCP-сервер (<code>swag2mcp mcp</code>), чтобы изменения вступили в силу.</p></blockquote><h2 id="иерархия" tabindex="-1">Иерархия <a class="header-anchor" href="#иерархия" aria-label="Permalink to &quot;Иерархия&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Спецификация (domain, например &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Коллекция 1 (файл спецификации, например forecast.yml)</span></span>
<span class="line"><span>        └── Тег 1 (категория)</span></span>
<span class="line"><span>              └── Эндпоинт (GET /api/forecast)</span></span>
<span class="line"><span>              └── Эндпоинт (POST /api/forecast)</span></span>
<span class="line"><span>        └── Тег 2</span></span>
<span class="line"><span>              └── Эндпоинт (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Коллекция 2 (файл спецификации, например air-quality.yml)</span></span>
<span class="line"><span>        └── Тег 3</span></span>
<span class="line"><span>              └── Эндпоинт (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const E=n(t,[["render",o]]);export{m as __pageData,E as default};
